package ktanesolver.module.modded.regular.ikea;import java.util.*;import org.springframework.stereotype.Service;import ktanesolver.annotation.ModuleInfo;import ktanesolver.dto.ModuleCatalogDto;import ktanesolver.entity.*;import ktanesolver.enums.ModuleType;import ktanesolver.logic.*;
@Service@ModuleInfo(type=ModuleType.IKEA,id="qSwedishMaze",name="IKEA",category=ModuleCatalogDto.ModuleCategory.MODDED_REGULAR,description="Rank the Swedish labels, derive the rotated store, and map its route to buttons.",tags={"maze","Swedish","colors","buttons"})
public class IkeaSolver extends AbstractModuleSolver<IkeaInput,IkeaOutput>{static final List<String>PRODUCTS=List.of("SÄNG","SKÅP","STOL","GARDINER","SKRIVBORD","FLÄKT","TÄCKE","HANDDUK"),ORDERS=List.of("NEWS","SEWN","NESW","WNSE","NWES","ENSW","WENS","SWEN"),YELLOW=List.of("FÄRG","GODIS","ÅTTAHÖRNING","KÖTTBULLE","DRAKE","TROLLKARL","OST","SKO","TVÄTTBJÖRN","ENHÖRNING","MÅLA","SKJORTA","VALP","KÄNGA","HÖRLURAR","SKÅL"),BLUE=List.of("KÖTTBULLE","SKÅL","OST","TROLLKARL","SKO","KÄNGA","GODIS","VALP","HÖRLURAR","SKJORTA","MÅLA","FÄRG","ENHÖRNING","TVÄTTBJÖRN","ÅTTAHÖRNING","DRAKE"),PATHS=List.of("SSWWSWWNNNWN","SSESSWWWNNNWSSSWSSS","NWWSSSEEEENNNNNWN","EESSESSWWWSW","WWSSEESSWWSEESENNNNNNNW","SWSESWSEEENNNNNN","NNWWSSWWNNWSSWSEEEEEEEN","WNWSWNWSSSEEEEEE","WWSWWNNNEEENWWWNWWW","SEENNNWWWWSSSSSES","WWNNWNNEEENE","EENNWWNNEENWWNWSSSSSSSE","NNWNNEEESSSENNNENNN","SSEENNEESSENNENWWWWWWWS","ESENESENNNWWWWWW","WSSEEENNNNWWWWWSW");static final Map<String,String>ALIASES=aliases();
	@Override protected SolveResult<IkeaOutput>doSolve(RoundEntity round,BombEntity bomb,ModuleEntity module,IkeaInput input){if(input==null||input.buttons()==null||input.buttons().size()!=5||input.buttons().stream().anyMatch(b->b==null||b.color()==null))return failure("Enter all five button labels and background colors");List<String>labels=input.buttons().stream().map(b->normalize(b.label())).toList();List<Integer>products=new ArrayList<>();for(int i=0;i<5;i++)if(PRODUCTS.contains(labels.get(i)))products.add(i);if(products.size()!=1)return failure("Exactly one button must be a product");int product=products.getFirst(),productType=PRODUCTS.indexOf(labels.get(product));List<String>ranking=input.buttons().get(product).color()==IkeaInput.Color.YELLOW?YELLOW:BLUE;Set<String>brands=new HashSet<>();for(int i=0;i<5;i++)if(i!=product){if(!ranking.contains(labels.get(i)))return failure("Every non-product label must be a brand from Table 2");if(!brands.add(labels.get(i)))return failure("Brand labels must be distinct");}List<Integer>ranked=new ArrayList<>();for(String brand:ranking)for(int i=0;i<5;i++)if(labels.get(i).equals(brand))ranked.add(i);String order=ORDERS.get(productType);String[]directions={"X","X","X","X","X"};int store=0;for(int rank=0;rank<4;rank++){int button=ranked.get(rank);directions[button]=String.valueOf(order.charAt(rank));if(input.buttons().get(button).color()==IkeaInput.Color.YELLOW)store|=1<<(3-rank);}String path=PATHS.get(store);List<Integer>presses=new ArrayList<>();for(char direction:path.toCharArray()){int button=Arrays.asList(directions).indexOf(String.valueOf(direction));if(button<0)return failure("A path direction was not assigned to a button");presses.add(button+1);}return success(new IkeaOutput(List.copyOf(presses),path,List.of(directions),store));}
	private static String normalize(String value){String key=value==null?"":value.trim().toUpperCase(Locale.ROOT);return ALIASES.getOrDefault(key,key);}private static Map<String,String>aliases(){String[]english={"BED","CABINET","CHAIR","CURTAINS","DESK","FAN","QUILT","TOWEL","COLOR","CANDY","OCTAGON","MEATBALL","DRAGON","WIZARD","CHEESE","SHOE","RACCOON","UNICORN","PAINT","SHIRT","PUPPY","BOOT","HEADPHONES","BOWL"},swedish={"SÄNG","SKÅP","STOL","GARDINER","SKRIVBORD","FLÄKT","TÄCKE","HANDDUK","FÄRG","GODIS","ÅTTAHÖRNING","KÖTTBULLE","DRAKE","TROLLKARL","OST","SKO","TVÄTTBJÖRN","ENHÖRNING","MÅLA","SKJORTA","VALP","KÄNGA","HÖRLURAR","SKÅL"};Map<String,String>map=new HashMap<>();for(int i=0;i<english.length;i++)map.put(english[i],swedish[i]);return Map.copyOf(map);}}
